    background = max(counts, key=counts.get)

    # The embedded five-cell pattern is the stamp; the separate sparse color
    # marks its center positions.
    runs = []
    for row_index, row in enumerate(grid):
        col = 0
        while col < w:
            if row[col] == background:
                col += 1
                continue
            start = col
            while col < w and row[col] != background:
                col += 1
            if col - start >= 5:
                runs.append((row_index, start, row[start:col]))
    if not runs:
        return [row[:] for row in grid]

    _, _, pattern = max(runs, key=lambda run: len(run[2]))
    center = len(pattern) // 2
    marker = min(
        (color for color in counts if color != background and color not in pattern),
        key=lambda color: counts[color],
        default=None,
    )
    if marker is None:
        return [row[:] for row in grid]

    result = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker:
                for offset, color in enumerate(pattern):
                    target_col = c + offset - center
                    if 0 <= target_col < w:
